 $('#breadcrumb').textContent='交通孤岛决策实验 / '+group.title;
 $('#scenario').innerHTML=E.scenarios.map(v=>`<option value="${v.id}" ${v.id===state.scenario?'selected':''}>${v.name}</option>`).join('');
